"""Freeze the actual changed definitions for bounded Bedrock counterexample review."""
import json,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];RUN=ROOT/'research/source-store/mece-closure-v20-20261011'
def read(p):return json.loads(p.read_text())
def write(p,v):p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
assert not (RUN/'catalogue-after.json').exists(),'Do not overwrite a frozen review'
data=read(ROOT/'dist/data/operations.json');root=read(ROOT/'data/mece-v20-root-dispositions.json');by={w['id']:w for w in data['works']}
ids=root['added_work_ids']+root['edited_work_ids'];assert len(ids)==len(set(ids))==21
write(RUN/'catalogue-after.json',data)
keys=['id','title','actor_role','object_key','outcome_key','discriminator','definition','includes','excludes']
catalogue=[{k:w[k] for k in keys} for w in by.values()]
instructions='''Return JSON only {"rows":[{"id":exact assigned current work id,"decision":"retain|needs_boundary_edit|needs_source|merge_proposal","work_ids":current IDs only,"evidence_section_ids":supplied IDs only,"reason":Korean,"counterexamples":[Korean],"next_action":Korean}]}. Review changed actual definitions against entire current catalogue and actual operative own quotes. Cite section IDs only. A source's historical/conditional status does not disqualify it as EDITORIAL FUNCTION evidence, but cannot prove current global law, executed contract, provider availability or UI observation. Check true role/object/result and overlapping results. No product/method/date/output quantity/viewpoint clones; source parents are not financial work. Specific source conditions cannot become universal rights. Registered holder transfer differs from nominee holding and position movement, but require actor responsibility and effect conditions. Series estate segregation is not Class fee allocation or every fund's legal formation. NAV is an aggregate unit price input; final subscription/redemption price can include fees. Loan assignment transfers lender position whereas participation leaves original lender obligated. Master amendments are shared agreed terms; unilateral scheme participation change includes temporary restrictions, permanent relationship end is separate. Voluntary versus forced termination are conditions of one relationship end unless a genuinely independent authority judgment is missing: identify exact proposed object/outcome, not merely different trigger. Residual duties remain and are not a single new work. Forecast scalar values and distributions are methods/outputs of prospective analytical results, not two new works; contrast current valuation purpose and realized performance. Insurance and reinsurance internal underwriting share responsibility/result, separate shared contract formation. Receivable title purchase and paying its agreed advance are separate legal responsibility outputs; paying loan funds requires loan structure. Customer input with unspecified invoice finance structure must retain both legal branches and never automatically choose. Verify definition claims supported; raise real defects and precise edits. Never approve global MECE, independent humans or provider collection. Return every assigned ID exactly once.'''
for n,start in enumerate(range(0,len(ids),7),1):
    rows=[by[i] for i in ids[start:start+7]];sections={}
    for w in rows:
        for k,r in enumerate(w['refs']):
            if r.get('exact_quote') and not r.get('context_requires_review'):sections[w['id']+':proof:'+str(k)]=r['exact_quote']
    job=dict(id=f'current-delta-v20-{n:02}',model='claude-opus-5',max_tokens=18000,instructions=instructions,input={'catalogue':catalogue,'changed_definitions':rows,'operative_sections':sections,'root_conditions':root['root_corrections']},expected_ids=[w['id'] for w in rows],row_key='id',work_ids=list(by),sections=sections,grounded_section_ids=True)
    write(RUN/'inputs'/(job['id']+'.json'),job)
job=dict(id='quality-steward-v20-bounded',model='claude-sonnet-5',max_tokens=18000,instructions=instructions+' Act as the practitioner-quality critic. Include foreseeable wrong decisions during real screen creation and expose all coverage gaps. Assess the root composites and source qualifications critically, no blanket agreement.',input={'catalogue':catalogue,'changed_definitions':[by[i] for i in ids],'root_dispositions':root,'operative_sections':{w['id']+':proof:'+str(k):r['exact_quote'] for w in [by[i] for i in ids] for k,r in enumerate(w['refs']) if r.get('exact_quote') and not r.get('context_requires_review')}},expected_ids=ids,row_key='id',work_ids=list(by),grounded_section_ids=True)
job['sections']=job['input']['operative_sections'];write(RUN/'inputs'/(job['id']+'.json'),job)
print(json.dumps({'current':len(by),'changed':len(ids),'jobs':4,'definition_sha256':hashlib.sha256((RUN/'catalogue-after.json').read_bytes()).hexdigest()}))
